INSERT INTO `cms_content` (`page_key`, `content`) VALUES ('general', '{"siteName":"National Plasto Products Pvt. Ltd.","tagline":"Precision Plastic Moulded Products. Built for India.","contactEmail":"info@nationalplasto.com","salesEmail":"sales@nationalplasto.com","dealerEmail":"dealer@nationalplasto.com","exportEmail":"export@nationalplasto.com","contactPhone":"+91 98300 12345","landline":"+91 33 2289 1234","tollFree":"1800 123 4567","whatsapp":"+91 98300 12345","headOffice":"135G, Shyama Prasad Mukherjee Road, Sterling Apartment, First Floor, Next to Mahindra Showroom, Kolkata, West Bengal 700026","cataloguePdfUrl":"docs/national-plasto-catalogue-2026.pdf","workingHours":"Monday – Saturday: 9:30 AM to 6:30 PM","socialLinks":{"facebook":"https://www.facebook.com/share/1GMoEgyWs7/?mibextid=wwXIfr","linkedin":"https://www.linkedin.com/company/nationalplasto/","instagram":"https://www.instagram.com/national_plasto_group/","amazon":"https://www.amazon.in/stores/page/0DC6798F-D636-4A69-8FC0-2BE41AE507DD?isPreview","flipkart":"https://www.flipkart.com/search?q=npm%20national"}}');
INSERT INTO `cms_content` (`page_key`, `content`) VALUES ('home', '{"hero":{"eyebrow":"Since 1997","title1":"Shaping Spaces, Engineering Trust","title2":"Designed for Life, Built for Generations","title3":"Empowering India with Premium Living","title":"Shaping Spaces, Engineering Trust","videoUrl":"videos/hero/national-plasto-overview.mp4","videoPoster":"images/hero/overview-video-poster.jpg","bannerImage":"images/brand/company-photo.jpg","ctaText":"About the Company","ctaLink":"about.html"},"virtues":[{"title":"Integrity","desc":"Our mission is to operate with integrity, foster a culture of the utmost respect for individuals and serve as a catalyst for development.","icon":"images/icons/hand.gif"},{"title":"Customer Centricity","desc":"With continuous innovation and efficiency, we aim to provide consistent products and services that improve the quality of life and exceed customer expectations.","icon":"images/icons/peoples.gif"},{"title":"Delivering Excellence","desc":"Our innovations have been backed by unparalleled quality that has withstood the effect of time throughout the years.","icon":"images/icons/delivering_excellence.gif"},{"title":"Innovation","desc":"Painstaking efforts and research behind every new development help us serve products that truly benefit humanity and the environment.","icon":"images/icons/innovation.gif"},{"title":"People First","desc":"National Plasto has always placed a great emphasis on taking care of those who are associated with us as they are one of our greatest assets.","icon":"images/icons/people_first.gif"},{"title":"Empowerment","desc":"Our team of experts and our workforce are our biggest assets. Empowering them every step of the way constantly helps us deliver only the best.","icon":"images/icons/empowerment.gif"}],"cmdTestimonial":{"quote":"Every business goes through difficult phases. What matters is not avoiding losses, but learning from them and growing bigger and better each time. My father taught me that how you treat people matters as much as how you run a business - that belief has shaped this company since 1997, and it continues to guide how we build for the future.","name":"Ratan Kumar Sharma","role":"Chairman & Managing Director","photo":"images/team/ratan-kumar-sharma-cutout.webp","btnText":"Meet Our Management","btnLink":"about.html#leadership"},"metricsSection":{"heading":"India\'s Leading Precision Plastic Processor","desc":"Powered by four ISO-certified manufacturing plants and a family-led management team, National Plasto has been making plastic moulded furniture for every space and every need since 1997.","stats":[{"value":"29","unit":"+ Years","label":"Industrial Pedigree"},{"value":"15","unit":"+ States","label":"Pan-India Presence"},{"value":"4","unit":"Plants","label":"Manufacturing Plants"},{"value":"4","unit":"Brands","label":"Brands & Divisions"},{"value":"1,200","unit":"+","label":"Products in Range"},{"value":"500","unit":"+","label":"Distributors & Dealers"},{"value":"1000","unit":"+","label":"Workforce Strength"},{"value":"ISO ? CE ? BIFMA","unit":"","label":"Certified Plants"}]},"plantHighlights":[{"title":"Festival","image":"data:image/jpeg;base64,","link":"manufacturing.html"},{"title":"Happy Family","image":"data:image/jpeg;base64,","link":"products.html"}],"brandsSection":{"title":"Our Brands","subtitle":"Four iconic brands engineered for every home, office, and institution.","brands":[{"name":"NEXT - Premium Furniture","tagline":"Premium Virgin Plastic Furniture","desc":"Designer finishes, rich pastels, and premium ergonomic contours for modern living.","image":"images/divisions/next.jpg","logo":"images/brand/company-next-logo.png","link":"products.html?brand=next"},{"name":"NATIONAL - Moulded Furniture","tagline":"Value, Variety and Trust for Every Space","desc":"Eastern India\'s most trusted household seating, tables, and multi-tier utility storage.","image":"images/divisions/national.jpg","logo":"images/brand/company-national-logo.png","link":"products.html?brand=national"},{"name":"CAPTAIN - Economical Furniture","tagline":"Economical Furniture for Everyday Use","desc":"Robust, lightweight, high-utility monoblock chairs built for demanding daily commercial use.","image":"images/divisions/captain.jpg","logo":"images/brand/captain-logo.png","link":"products.html?brand=captain"},{"name":"SAPPHIRE - Value Seating","tagline":"Distinct Value Seating Range","desc":"Engineered heavy-duty seating with sleek modern aesthetics at exceptional value.","image":"images/divisions/sapphire.jpg","logo":"images/brand/sapphire-logo.png","link":"products.html?brand=sapphire"}]},"milestones":[{"year":"1997","date":"Howrah, West Bengal ? The Beginning","desc":"National Plasto began its journey in Howrah, West Bengal, establishing the foundation for a manufacturing business built on quality, reliability, and customer trust.","image":"images/home/milestone-1997.jpg"},{"year":"2007","date":"Guwahati, Assam ? Expanding to the Northeast","desc":"The expansion into Guwahati strengthened National Plasto\'s presence in Northeast India, bringing manufacturing closer to regional markets and supporting a wider distribution network.","image":"images/home/milestone-2007.jpg"},{"year":"2010","date":"Roorkee, Uttarakhand ? Strengthening Northern Operations","desc":"The establishment of the Roorkee facility marked another important step in the company\'s growth, strengthening manufacturing capabilities and improving its reach across northern India.","image":"images/home/milestone-2010.jpg"},{"year":"2012","date":"Hajipur, Bihar ? Building a Stronger Manufacturing Network","desc":"The Hajipur expansion further strengthened National Plasto\'s manufacturing footprint, supporting broader market coverage and the company\'s continued commitment to serving customers across India.","image":"images/home/milestone-2012.jpg"},{"year":"2026","date":"Pan-India ? Continuing Our Journey","desc":"National Plasto continues its nationwide journey with 4 advanced manufacturing plants, 470+ verified partners across 17 states, and sustainable polymer innovations driving the future of furniture in India.","image":"images/home/milestone-2026.jpg"}],"sustainability":{"title":"Sustainability","p1":"At National Plasto, responsible manufacturing is part of how we make furniture for every space and every need. Our NATIONAL, CAPTAIN and SAPPHIRE ranges are built with reprocessed plastic, giving used plastic a long second life as durable everyday furniture.","p2":"Every one of our four plants - Howrah, Guwahati, Roorkee and Hajipur - is independently certified for environmental management, and our energy use is managed under ISO 50001.","btnText":"Know More","btnLink":"manufacturing.html#certifications"},"touchingLives":{"title":"Furniture For Every Community","desc":"From classrooms and community halls to homes in Tier 2 and Tier 3 towns, National Plasto makes durable seating affordable for everyone. We give used plastic a second life through our reprocessed ranges, keep our 1,000+ strong workforce safe under ISO 45001, and grow together with the dealers and families who depend on us.","image":"images/brand/furniture-for-every-community.jpg","btnText":"Our Values","btnLink":"about.html"},"innovativeProducts":{"title":"Innovating Products, Creating Impact","desc":"Every National Plasto product is made to last and designed to make an Impact. From premium NEXT designs to everyday CAPTAIN and SAPPHIRE seating, our 360+ models bring comfort, durability and affordability to homes, businesses and institutions across India.","image":"images/business/moulded-furniture.jpg","btnText":"Explore Products","btnLink":"products.html"},"uniqueStory":{"title":"What makes us unique?","desc":"Since 1997, National Plasto has been making moulded plastic furniture for every space and every need. Four ISO-certified plants, four brands across price points and a Pan-India dealer network let us deliver durable, affordable furniture to homes, businesses and institutions across India.","image":"images/brand/company-photo.jpg","buttonText":"Know Our Story","buttonLink":"about.html"},"reels":[{"name":"NEXT - Premium Virgin Plastic Furniture","poster":"images/banner/next.jpg","video":"images/banner/next.mp4"},{"name":"NATIONAL - Value, Variety & Trust","poster":"images/banner/national.jpg","video":"images/banner/national.mp4"},{"name":"CAPTAIN - Economical Everyday Furniture","poster":"images/banner/captain.jpg","video":"images/banner/captain.mp4"},{"name":"SAPPHIRE - Distinct Value Seating","poster":"images/banner/sapphire.jpg","video":"images/banner/sapphire.mp4"}],"network":{"title":"Pan-India Presence. Rapid Supply Chain.","subtitle":"Four state-of-the-art plastic furniture manufacturing facilities powering over 500 authorized distributor and dealer hubs.","plantsStat":"4","dailyCapacityStat":"50,000+","dealersStat":"500+","statesStat":"18"}}');
INSERT INTO `cms_content` (`page_key`, `content`) VALUES ('about', '{"hero":{"breadcrumb":"About Us","title":"Rooted in 1981, Incorporated in 1997","subtitle":"Over four decades of industrial heritage and nearly three decades of pioneering plastic injection moulding excellence.","bannerImage":"images/brand/aboutus.png"},"overview":{"title":"Rooted in 1981, Incorporated in 1997","leadText":"Over four decades of industrial heritage and nearly three decades of pioneering plastic injection moulding excellence.","desc":"Tracing foundational commercial roots back to 1981, National Plasto Products Pvt. Ltd. (NPPL) was incorporated on 29 October 1997 under the visionary leadership of Mr. Ratan Kumar Sharma. From an initial manufacturing plant in Kolkata, West Bengal, NPPL has expanded into a nationwide plastic furniture manufacturing leader with 4 advanced manufacturing hubs across India. Operating high-tonnage microprocessor injection moulding machinery from 80T up to 1,200T across over 2,00,000 sq. ft. of production floor space, we design and produce over 1,000 active moulds and products. Our 4-tier brand architecture—NEXT, NATIONAL, SAPPHIRE, and CAPTAIN—delivers ergonomic, durable, and aesthetically superior moulded furniture to millions of Indian homes, institutions, and businesses.","image":"images/brand/aboutus.png"},"missionVision":{"vision":"To be India\'s most trusted plastic-moulded furniture brand, setting the benchmark for ergonomic comfort, structural durability, and sustainable plastic manufacturing accessible to every home and enterprise.","mission":"Delivering high-value, long-lasting plastic-moulded furniture solutions through continuous technological innovation, rigorous 200kg load testing, and an empowered pan-India network of over 500 distribution partners."},"pillars":[{"number":"01","title":"Precision in Every Product","desc":"Our advanced manufacturing capabilities combine modern technology and precision engineering to deliver consistent quality, superior finishes and dependable performance.","image":"images/about/01-advanced-manufacturing.png"},{"number":"02","title":"Built for Efficiency. Ready for Growth.","desc":"Our integrated manufacturing operations are designed for efficiency, consistency and reliable supply, helping us meet diverse customer requirements with confidence.","image":"images/about/02-manufacturing-at-scale.jpg"},{"number":"03","title":"Quality You Can Trust","desc":"Every product reflects our commitment to quality, strength and durability. Careful inspection and consistent manufacturing standards help ensure reliable performance in everyday use.","image":"images/about/03-quality-reliability-lab.jpg"},{"number":"04","title":"Efficiency in Every Process","desc":"Our streamlined manufacturing processes focus on precision, productivity and consistency. By optimizing workflows and maintaining high operational standards, we deliver dependable quality.","image":"images/about/04-operational-excellence-facility.png"}],"managementIntro":{"title":"Our Management","p1":"Since 1997, National Plasto Products Pvt. Ltd. (NPPL) has been manufacturing plastic moulded furniture designed for every space and every need. From homes and educational institutions to healthcare facilities, government establishments and businesses across the country, our products have become part of everyday environments across India.","p2":"What began as a single manufacturing unit has grown into four manufacturing plants located in Howrah (West Bengal), Guwahati (Assam), Roorkee (Uttarakhand) and Hajipur (Bihar). All NPPL manufacturing units are ISO certified across various levels, reflecting our commitment to consistent processes and quality standards.","p3":"Behind this growth is a family-led management team that brings together decades of hands-on experience, strong operational knowledge and clear defined responsibilities across finance, production, sales and marketing."},"leadership":[{"name":"Mr. Ratan Kumar Sharma","role":"Chairman & Managing Director","photo":"images/team/ratan-kumar-sharma-cmd.jpg","bio":"With 18 years of experience in the plastic furniture industry prior to establishing National Plasto Products Pvt. Ltd., Mr. Ratan Kumar Sharma brought extensive industry knowledge and practical experience to the foundation of the company in 1997.\\n\\nHe founded National Plasto Products Pvt. Ltd. in 1997 and has led its journey from a single manufacturing unit to four plants across Howrah, Hajipur, Guwahati and Roorkee.\\n\\nOver nearly three decades, he has built the company on a foundation of perseverance, relationships and the values passed down by his father, whose guidance continues to influence his approach to business and leadership.\\n\\nUnder his leadership, NPPL has grown not only in scale and turnover, but also in the trust and respect it has built among its employees, partners and associates. He believes that every challenge presents an opportunity to learn, adapt and return stronger.","quote":"“Every business goes through difficult phases. What matters is not avoiding losses, but learning from them and growing bigger and better each time. My father taught me that how you treat people matters as much as how you run a business — that belief has shaped this company since 1997, and it continues to guide how we build for the future.” — Mr. Ratan Kumar Sharma, Chairman & Managing Director"},{"name":"Mr. Rajkumar Sharma","role":"Director – Finance","photo":"images/team/rajkumar-sharma-director-finance.jpg","bio":"Mr. Rajkumar Sharma, the eldest of the family and elder brother of Mr. Ratan Kumar Sharma, has overseen the company\'s financial operations since its inception in 1997.\\n\\nAs the senior-most member of the management team, his steady and disciplined approach to financial management and accounts has been a constant strength behind the company\'s growth. His experience and practical understanding continue to play an important role in shaping key financial decisions across the organisation and its four manufacturing units.","quote":"Strong financial management and transparent operations are the foundation of our long-term success."},{"name":"Late Mr. Sukhram Sharma","role":"Director – Production (In Memoriam)","photo":"images/team/sukhram-sharma-director-production.jpg","bio":"Mr. Sukhram Sharma, the youngest brother of Mr. Raj Kumar Sharma and Mr. Ratan Kumar Sharma, was an integral part of National Plasto Products Pvt. Ltd. and made significant contribution to the Company\'s growth and establishment.\\n\\nHe was closely involved with the factory and production operations, where his hands-on approach and dedication earned him the trust and respect of the entire factory team. He shared a strong bond with the employees and treated them like family.\\n\\nMr. Sukhram Sharma passed away three years ago, leaving behind a legacy of dedication, relationships and contribution to the Company\'s growth. He will always be remembered as a valued member of the NPPL family.","quote":"Our machines shape the furniture, but it is our people who shape the quality, consistency, and trust behind every National Plasto product."},{"name":"Mr. Bhavesh Sharma","role":"Executive Director","photo":"images/team/bhavesh-sharma-executive-director.jpg","bio":"Mr. Bhavesh Sharma, son of Mr. Ratan Kumar Sharma, oversees production, sales and marketing across all four manufacturing units, working closely with teams to maintain consistency in quality, output and operations.\\n\\nA key part of the company\'s next phase of growth has been its expansion into E-Commerce. Under his leadership, NPPL has strengthened its presence on platforms such as Amazon and Flipkart, extending the company\'s reach beyond traditional dealer networks.\\n\\nWith a hands-on approach and focus on exploring new markets, he continues to drive the company\'s growth while remaining firmly connected to the values on which NPPL was built.","quote":"With decades of dealer trust and an expanding presence across digital marketplaces, we are taking National Plasto products to more homes and businesses across the country."},{"name":"Mr. Devesh Sharma","role":"Executive Director","photo":"images/team/devesh-sharma-executive-director.jpg","bio":"Mr. Devesh Sharma, the youngest member of the family and son of Late Mr. Sukhram Sharma, oversees production and sales operations across the company\'s manufacturing units.\\n\\nWorking closely with the teams on a day-to-day basis, he contributes to operational efficiency and the company\'s continued expansion. His attention to detail, willingness to embrace new challenges and commitment to the business reflect the evolving role of the next generation in taking NPPL forward.\\n\\nAs part of the next generation of leadership, he continues to carry forward the company\'s values while contributing to its future growth and ambitions.","quote":"“Operational excellence is achieved every day through precision engineering, team empowerment, and an unwavering commitment to quality standards.”"}],"stats":[{"label":"Foundational Heritage","value":"45+ Years (Since 1981)"},{"label":"Plastic-Moulded Furniture Excellence","value":"29+ Years (Est. 1997)"},{"label":"Modern Plants","value":"4 (Howrah, Guwahati, Roorkee, Hajipur)"},{"label":"Active SKUs & Moulds","value":"1,000+"}]}');
INSERT INTO `cms_content` (`page_key`, `content`) VALUES ('products', '{"hero":{"breadcrumb":"Products","title":"Products & Complete Catalogue","subtitle":"Browse 360+ models of moulded chairs, dining sets, tables, stools and storage.","bannerImage":"images/brand/products.png"},"shopByBrandHeader":{"title":"Shop by brand","desc":"Four brands, one promise — quality moulded furniture at every price point."},"exploreCollectionsHeader":{"title":"Explore our collections","desc":"Browse through a wide range of chairs, tables, dining sets, stools, storage and kids furniture."},"collections":[{"name":"Arm Chairs","count":"135 Products","desc":"Sturdy, comfortable moulded arm chairs for homes, offices and events.","image":"images/collections/arm-chairs.jpg","link":"products.html?cat=arm-chairs"},{"name":"Premium Arm Chairs","count":"2 Products","desc":"Cushioned premium arm chairs with a rich finish.","image":"images/collections/premium-arm-chairs.jpg","link":"products.html?cat=premium-arm-chairs"},{"name":"Armless Chairs","count":"52 Products","desc":"Space-saving, stackable armless chairs for every room.","image":"images/collections/armless-chairs.jpg","link":"products.html?cat=armless-chairs"},{"name":"Premium Armless Chairs","count":"4 Products","desc":"Premium cushioned armless chairs for dining and lounges.","image":"images/collections/premium-armless-chairs.jpg","link":"products.html?cat=premium-armless-chairs"},{"name":"Metallic Chairs","count":"11 Products","desc":"Chairs with a metallic finish for a modern look.","image":"images/collections/metallic-chairs.jpg","link":"products.html?cat=metallic-chairs"},{"name":"Steel Moulded Chairs","count":"3 Products","desc":"Moulded seats on strong steel legs for cafes and offices.","image":"images/collections/steel-moulded-chairs.jpg","link":"products.html?cat=steel-moulded-chairs"},{"name":"Baby Chairs","count":"14 Products","desc":"Bright, safe and lightweight chairs for little ones.","image":"images/collections/baby-chairs.jpg","link":"products.html?cat=baby-chairs"},{"name":"Stools","count":"39 Products","desc":"Strong, portable stools for kitchens, shops and everyday use.","image":"images/collections/stools.jpg","link":"products.html?cat=stools"},{"name":"Tables","count":"51 Products","desc":"Durable, easy-to-clean tables for homes and businesses.","image":"images/collections/tables.jpg","link":"products.html?cat=tables"},{"name":"Dining Sets","count":"45 Products","desc":"Table and chair sets for family dining, indoors and out.","image":"images/collections/dining-sets.jpg","link":"products.html?cat=dining-sets"},{"name":"Trolleys & Racks","count":"4 Products","desc":"Multi-tier utility racks and trolleys for smart storage.","image":"images/collections/trolleys-and-racks.jpg","link":"products.html?cat=trolleys-and-racks"},{"name":"Wardrobes","count":"2 Products","desc":"Lockable plastic wardrobes for clutter-free rooms.","image":"images/collections/wardrobes.jpg","link":"products.html?cat=wardrobes"}],"orderTimingNotice":{"badge":"Fast Dispatch Guarantee","title":"Pan-India Order Processing","desc":"All dealer and bulk orders are dispatched within 24 to 48 hours directly from the nearest regional plant."},"brochure":{"title":"Download National Plasto Product Catalogue 2026","desc":"Complete 2026 product range with exact specifications, dimensions, color palettes, and container packing sizes.","pdfUrl":"docs/national-plasto-catalogue-2026.pdf","btnText":"Download Catalogue PDF"}}');
INSERT INTO `cms_content` (`page_key`, `content`) VALUES ('manufacturing', '{"hero":{"breadcrumb":"Manufacturing","title":"World-Class Plastic Furniture Manufacturing Facilities","subtitle":"Robotic injection moulding, high-tonnage precision machinery & ISO 9001:2015 accredited plants.","bannerImage":"images/brand/company-photo.jpg"},"intro":{"title":"Industrial Manufacturing Capabilities","desc":"Spanning four integrated production hubs, National Plasto converts over 35,000 metric tonnes of virgin plastic annually into precision-engineered moulded products.","image":"images/brand/company-photo.jpg"},"metrics":[{"number":"35,000","unit":"MT+","label":"Plastic Furniture Produced Annually"},{"number":"1,200","unit":"Tons","label":"Max Injection Moulding Clamp Force"},{"number":"200,000","unit":"Sq. Ft.","label":"Total Manufacturing Floor Space"},{"number":"100%","unit":"QA","label":"Rigorous 200kg Load & Drop Tested"}],"plants":[{"name":"Howrah Manufacturing Hub","region":"West Bengal","location":"Jalan Industrial Estate, Dakshin Jhapardaha, Howrah, West Bengal 711411","capacity":"18,000 Units / Day","machines":"16 Injection Moulding Machines (80T - 1,200T)","image":"images/home/plant-kl850.jpg"},{"name":"Guwahati Manufacturing Hub","region":"Assam","location":"E.P.I.P. Complex, Amingaon, Guwahati, Assam 781031","capacity":"12,000 Units / Day","machines":"12 Injection Moulding Machines (100T - 850T)","image":"images/home/milestone-2007.jpg"},{"name":"Roorkee Manufacturing Hub","region":"Uttarakhand","location":"Raipur Industrial Area, Bhagwanpur, Roorkee, Uttarakhand 247661","capacity":"10,000 Units / Day","machines":"10 Injection Moulding Machines (100T - 800T)","image":"images/home/milestone-2010.jpg"},{"name":"Hajipur Manufacturing Hub","region":"Bihar","location":"EPIP Industrial Area, Hajipur, Vaishali, Bihar 844101","capacity":"10,000 Units / Day","machines":"8 Injection Moulding Machines (100T - 650T)","image":"images/home/milestone-2026.jpg"}],"qualityTesting":{"title":"Quality Assurance & In-House Testing Laboratory","desc":"Every batch undergoes rigorous structural stress tests, UV exposure analysis, color fastness checks, and automated weight-bearing load tests up to 200kg.","tests":[{"name":"200kg Static Load Test","desc":"Simulates prolonged extreme weight bearing without plastic deformation."},{"name":"Drop Impact Test","desc":"Drop-tested from 1.5m at multiple angles to guarantee impact resistance."},{"name":"UV & Climate Aging","desc":"Weathering test to verify resistance against yellowing, cracking, and fading."},{"name":"Melt Flow Index (MFI)","desc":"Testing virgin plastic purity before feeding raw pellets into hoppers."}]}}');
INSERT INTO `cms_content` (`page_key`, `content`) VALUES ('distributor', '{"hero":{"breadcrumb":"Dealer Desk","title":"Partner With India\'s Fastest Growing Furniture Network","subtitle":"Join over 500+ successful distributors and dealers across 15+ states with assured margins and prompt factory dispatch.","bannerImage":"images/brand/dealer.jpg"},"benefits":{"title":"Dealer Desk Benefits & Direct Factory Supply","subtitle":"With its expanding manufacturing and distribution network across the nation, National Plasto offers lucrative margins, territorial protection, and direct factory supply.","badgeTitle":"Authorised Dealer Desk","badgeSubtitle":"Verified Partnership","bars":[{"punchline":"Earn Maximum Profit on Every Sale","subtext":"Lucrative distributor price margins with high-turnover annual volume rebates."},{"punchline":"Zero Competition in Your Territory","subtext":"Demarcated sales zones guaranteeing exclusive regional distribution rights."},{"punchline":"Fast-Moving Models Across 4 Brands","subtext":"Complete portfolio covering Next, National, Captain & Sapphire furniture."},{"punchline":"Direct Supply from 4 Mega Plants","subtext":"Uninterrupted factory shipments backed by high-tonnage injection machines."}]},"unique":{"heading":"What makes us unique?","desc":"National Plasto is an approved partner and trusted manufacturer to major commercial enterprises and over 2,500+ authorized dealers across India. With over 29 years of furniture excellence, our high-precision plastic moulded furniture and material handling solutions are manufactured at 4 high-tech, ISO 9001, 14001, 45001, 50001, CE, and BIFMA-certified plants.","bannerImage":"images/ghj.png","btnText":"KNOW OUR STORY"},"cta":{"heading":"Ready to Grow With National Plasto?","desc":"Bring a trusted product portfolio to your market and build a stronger business with us.","primaryBtnText":"BECOME A DEALER","catalogueBtnText":"DOWNLOAD CATALOGUE"},"whyPartner":{"title":"Why Become a National Plasto Partner?","subtitle":"Experience unmatched trade support, clear margins, and an extensive catalogue.","perks":[{"title":"Direct Factory Pricing","desc":"Enjoy Tier-1 manufacturer margins with no intermediary cuts."},{"title":"Priority Plant Dispatch","desc":"Orders dispatched within 24-48 hours from nearest production hub."},{"title":"Exclusive Brand Territories","desc":"Protected regional distribution rights for qualified stocking dealers."},{"title":"Comprehensive POS & Marketing","desc":"Free display stands, flex banners, product sample kits, and digital catalogues."},{"title":"100% Replacement Guarantee","desc":"Hassle-free replacement for any transit damage or manufacturing imperfections."},{"title":"Annual Volume Rebates","desc":"Tiered incentives and annual bonus schemes for high-performing partners."}]},"process":{"title":"4 Simple Steps to Dealership","steps":[{"step":"01","title":"Apply Online","desc":"Submit your dealership interest form with firm details and GST number."},{"step":"02","title":"Regional Verification","desc":"Our regional sales manager connects with you to discuss territory and demand."},{"step":"03","title":"Dealership Agreement","desc":"Finalize credit terms, catalog selection, and onboarding documentation."},{"step":"04","title":"First Dispatch","desc":"Receive your initial curated stock with complimentary marketing kits."}]},"contactInfo":{"hotline":"+91 98300 12345","email":"dealer@nationalplasto.com","hours":"Monday – Saturday: 9:30 AM to 6:30 PM","portalNotice":"Existing dealers can log in to check dispatch invoices and LR status."}}');
INSERT INTO `cms_content` (`page_key`, `content`) VALUES ('contact', '{"hero":{"breadcrumb":"Contact Us","title":"Contact National Plasto","subtitle":"Reach out to our corporate headquarters, manufacturing plants, or dealership helpdesk.","bannerImage":"images/brand/company-photo.jpg"},"corporateOffice":{"title":"National Plasto Products Pvt. Ltd. (Head Office)","address":"135G, Shyama Prasad Mukherjee Road, Sterling Apartment, First Floor, Next to Mahindra Showroom, Kolkata, West Bengal 700026","phone":"+91 98300 12345","landline":"+91 33 2289 1234","email":"info@nationalplasto.com","mapUrl":"https://www.google.com/maps/search/?api=1&query=135G+Shyama+Prasad+Mukherjee+Road%2C+Sterling+Apartment%2C+Kolkata%2C+West+Bengal+700026"},"factories":[{"name":"Howrah Plant (West Bengal)","address":"Jalan Industrial Estate, Dakshin Jhapardaha, Howrah, West Bengal 711411","phone":"+91 33 2669 0001","email":"howrah@nationalplasto.com"},{"name":"Guwahati Plant (Assam)","address":"E.P.I.P. Complex, Amingaon, Guwahati, Assam 781031","phone":"+91 361 284 0002","email":"guwahati@nationalplasto.com"},{"name":"Roorkee Plant (Uttarakhand)","address":"Raipur Industrial Area, Bhagwanpur, Roorkee, Uttarakhand 247661","phone":"+91 1332 235 003","email":"roorkee@nationalplasto.com"},{"name":"Hajipur Plant (Bihar)","address":"EPIP Industrial Area, Hajipur, Vaishali, Bihar 844101","phone":"+91 6224 271 004","email":"hajipur@nationalplasto.com"}],"supportChannels":{"general":"info@nationalplasto.com","dealership":"dealer@nationalplasto.com","sales":"sales@nationalplasto.com","tollFree":"1800 123 4567","whatsapp":"+91 98300 12345"}}');
INSERT INTO `cms_content` (`page_key`, `content`) VALUES ('policies', '{"hero":{"breadcrumb":"Policies","title":"Policies, Warranty & Consumer Care","subtitle":"Our commitment to quality, consumer trust, data privacy, and ethical manufacturing practices.","bannerImage":"images/brand/company-photo.jpg"},"qualityWarranty":{"title":"Quality Standards & 1-Year Structural Warranty","text":"National Plasto products are manufactured using 100% virgin polypropylene and precision computer-aided tooling. We warrant our moulded furniture against manufacturing structural defects, premature stress cracking, and unintended moulding flaws for a period of one (1) year from the date of retail purchase. This warranty does not cover normal wear and tear, intentional misuse, or exposure to excessive open heat sources."},"privacy":{"title":"Privacy & Data Protection Policy","text":"National Plasto respects your privacy. We collect minimal personal information (such as your name, business name, telephone number, and email address) exclusively to respond to your commercial inquiries, facilitate dealership applications, and fulfill catalogue requests. We do not sell, rent, or disclose your personal information to any third parties without your explicit consent."},"returnsReplacement":{"title":"Return & Replacement Policy","text":"For retail and institutional buyers, goods damaged during transit or found with manufacturing faults upon arrival must be reported within 48 hours of delivery along with photographic evidence. Our authorized dealership network or regional trade depot will promptly inspect and issue a 100% free product replacement."},"shippingDispatch":{"title":"Logistics, Shipping & Pan-India Dispatch","text":"With four strategically positioned production plants in Howrah, Guwahati, Roorkee, and Hajipur, National Plasto guarantees direct-to-warehouse dispatch within 24 to 48 hours of order confirmation. Transit times generally range from 1 to 4 business days depending on dealer destination across India."}}');
